// @ts-check
// module: the description of every key the machine's `host.json` (and its `tickets` block) and each project's `.agent-org/project.json` accept
//
// DATA ONLY, AND IT IMPORTS NOTHING. The readers keep their own validation (`host-config.ts`, `project-config.ts`, `settings.ts`, and the modules that
// read a key of their own): this file says what each key is, what it is for and what breaks when it is wrong, so the Settings page can show it. It
// is NOT the validator, and a key is not accepted because it is here. `config-schema.test.ts` ties the two together: a key a reader reads with no
// entry here fails it, and so does an entry for a key no reader reads.
//
// A key whose name starts with an underscore is prose in the file, read by nothing, and has no entry.
//
// THE NOTATION. A dotted path. `[]` is one element of a list (`tickets.deny[].pattern`). `<name>` is any key of a map (`clones.<name>`), and `<role>`
// is one of `github.identity`'s roles, shown once for each key the file names.
//
// WHICH READERS. The keys of the three validators (`host-config.ts` for the host file's top level and `units` and `beforeTick` of a project,
// `settings.ts` for the `tickets` block, `project-config.ts` for a project's declaration) and the keys of the four readers the org's plan names
// beside them (`workers.haikuBrief`, `workers.ceoOneShot`, `workers.orchestratorOneShot` and `emergencyPriority`). Other modules read further keys of
// these files (`machineryCanary`, `crashRecover`, `messaging`, `causes`, `roles`, `vocabulary`, `units.reports` and the other `units` names). They are
// not described here, and the page does not show them: that is the follow-up the Settings epic names.
//
// THE FIELDS. `absent` says what a key with no value in its file means: `off` (a switch that is off), `default` (the built-in `default` applies) or
// `unset` (nothing applies, and the feature it names is not on). `switch` marks a key whose value of `false` turns it off. `secret` marks a key that
// names a file of secret content: the page shows its path and whether the file exists, never its contents. `also` names further paths a key covers
// when it takes one of several shapes (`tickets.pick` is "assigned", `{ team }` or `{ project }`), so the drift test accepts each shape's keys.
//
// THE `edit` FIELD. Each entry says whether a save may change it. An editable entry names how the page reads its value (`input`), when a saved change is
// in force (`applies`, the vocabulary below) and, for a key whose wrong value can break the machine, a sentence saying what (`dangerous`). A key that
// cannot be edited says why: a container is changed through its keys, a list as a whole, and a key whose only reader does not refuse a bad value is
// shown, not changed. `config-schema.test.ts` pins the set of dangerous keys and that every editable entry has `applies`.
//
// `applies` is what the readers do with the key, as far as this file records it: `now` (read each time it is used), `board` (read when `ticket:serve`
// and `ticket:ui` start, so a restart), `unit` (read when the named units are rendered, so a reinstall and a restart), `none` (a running queue does not
// read it, as `tickets.max` once the queue file holds its own `max`).

export type File = "host.json" | "project.json" | "choice.json";

/** How the page reads a value to send: text, a number, true or false, or a JSON value (a list or an object). */
export type Input = "text" | "number" | "boolean" | "json";
export type Applies = "now" | "board" | "unit" | "none";
/** Whether a save may change the entry, and how. `unit` names the units a change is in force after; `note` says what else applies. */
export type Edit =
  | Readonly<{ editable: true; input: Input; applies: Applies; unit?: string; note?: string; dangerous?: string }>
  | Readonly<{ editable: false; why: string }>;

/** The in-force sentence of an editable entry, from its `applies`: what must restart before the value is read. The review of a change and the row of a key say it alike. */
export function inForceOf(edit: Extract<Edit, { editable: true }>, applies: Applies): string {
  const note = edit.note === undefined ? "" : ` ${edit.note}.`;
  if (applies === "now") return `in force now.${note}`;
  if (applies === "board") return `in force after the board restarts: ticket:serve and ticket:ui.${note}`;
  if (applies === "unit") return `in force after you reinstall and restart ${edit.unit ?? "the units this machine installs"}.${note}`;
  return "not in force: the queue keeps the number of workers it already has, so change it with Workers at once";
}

/** The groups the page shows, in this order. Each entry names one. */
export const GROUPS = ["Tracker", "Code host", "Publisher", "Reviewer", "Exposure", "Conventions plugin", "Workers", "Events", "Project", "Machine"] as const;
export type Group = (typeof GROUPS)[number];

export type Absent = "off" | "default" | "unset";

export type SchemaEntry = Readonly<{
  key: string;
  file: File;
  group: Group;
  /** The type, in words: what a value may be. */
  type: string;
  absent: Absent;
  /** The built-in default's value, in words, when `absent` is `default`; else null. */
  default: string | null;
  /** A key that turns something on or off: its value of `false` is off. */
  switch?: true;
  secret?: "path" | "keychain";
  /**
   * The exact command that sets a `secret` entry's value (A11-163), which the Settings page shows with a copy button because a secret is never typed in the page. `{value}` is the
   * setting's current value, and `{value|fallback}` takes `fallback` when the file holds none. A plugin's manifest must give one for each of its secret entries.
   */
  setCommand?: string;
  /** Further paths this key covers, for a key that takes one of several shapes. */
  also?: readonly string[];
  explanation: string;
  /** What goes wrong when the value is wrong. */
  breaks: string;
  edit: Edit;
  /**
   * The new key an old key still stands for (A11-144): the entry's readers read the old key as an alias, which `doctor --fix` moves to this key, and the
   * entry is not editable, so a save changes the new key.
   */
  aliasOf?: string;
}>;

/** The keys of the new-run, planning and ticket-writer choices, which the page's controls change and `choice.json` keeps. */
export type ChoicePart = "model" | "effort" | "planModel" | "planEffort" | "writerModel" | "writerEffort";

